package com.bank.coalesce.shuffle;

import com.bank.coalesce.model.PartitionStat;
import java.util.*;
import java.util.logging.Logger;

// Produces the INITIAL fixed number of shuffle partitions with real sizes.
public class ShuffleWriter {
    private static final Logger log = Logger.getLogger(ShuffleWriter.class.getName());

    // Simulate a filtered daily slice: most partitions tiny, a few modest.
    public List<PartitionStat> write(int fixedPartitions) {
        log.info(() -> "shuffle wrote fixed " + fixedPartitions + " partitions (static config)");
        List<PartitionStat> stats = new ArrayList<>();
        Random rnd = new Random(42);
        for (int i = 0; i < fixedPartitions; i++) {
            // Mostly very small partitions (filtered data).
            long bytes = 200_000 + rnd.nextInt(800_000); // 0.2–1.0 MB each
            stats.add(new PartitionStat(i, bytes));
        }
        return stats;
    }
}
