package com.bank.coalesce.shuffle;

import com.bank.coalesce.model.PartitionStat;
import java.util.*;
import java.util.logging.Logger;

// Merges contiguous small partitions toward the advisory target size.
public class PartitionCoalescer {
    private static final Logger log = Logger.getLogger(PartitionCoalescer.class.getName());
    private final long advisoryBytes;
    private final int minPartitions;

    public PartitionCoalescer(long advisoryBytes, int minPartitions) {
        this.advisoryBytes = advisoryBytes;
        this.minPartitions = minPartitions;
    }

    // Returns the coalesced group sizes (each group becomes one task).
    public List<Long> coalesce(List<PartitionStat> parts) {
        List<Long> groups = new ArrayList<>();
        long acc = 0;
        for (PartitionStat p : parts) {
            acc += p.getBytes();
            if (acc >= advisoryBytes) {   // group reached target → close it
                groups.add(acc);
                acc = 0;
            }
        }
        if (acc > 0) groups.add(acc);     // final partial group

        // Respect minimum partition count (don't collapse too far).
        while (groups.size() < minPartitions && groups.size() < parts.size()) {
            groups.add(0L);
        }
        log.info(() -> "coalesced " + parts.size() + " partitions => " + groups.size()
                + " (target " + advisoryBytes + "B)");
        return groups;
    }
}
