package com.bank.coalesce;

import com.bank.coalesce.model.PartitionStat;
import com.bank.coalesce.shuffle.*;
import java.util.List;
import java.util.logging.*;

public class CoalesceDemo {
    private static final Logger log = Logger.getLogger(CoalesceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new CoalesceLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Fixed 200 shuffle partitions from the static config.
        List<PartitionStat> parts = new ShuffleWriter().write(200);

        long totalBytes = parts.stream().mapToLong(PartitionStat::getBytes).sum();
        log.info(() -> "WITHOUT coalescing: next stage = " + parts.size()
                + " tasks for only " + (totalBytes / 1_000_000) + " MB of data");

        // Coalesce toward 64 MB, min 1 partition.
        List<Long> groups = new PartitionCoalescer(64_000_000, 1).coalesce(parts);
        log.info(() -> "WITH coalescing: next stage = " + groups.size()
                + " tasks (far less overhead)");
    }
}

